def get_country_by_iso2(code):
    for c in ISO_COUNTRIES:
        if c["iso2"].upper() == code.upper():
            return c
    return None

if __name__ == "__main__":
    print(f"Loaded {len(ISO_COUNTRIES)} ISO 3166-1 jurisdictions.")
    by_continent = {}
    for c in ISO_COUNTRIES:
        cont = c["continent"]
        by_continent[cont] = by_continent.get(cont, 0) + 1
    for cont, count in sorted(by_continent.items()):
        print(f" - {cont}: {count}")
